      ...(dest ? [{ label: t('newFolder'), icon: 'folder-plus', shortcut: 'Ctrl ⇧ N', onSelect: newFolder }, { label: t('upload'), icon: 'upload', onSelect: pick }] : []),
      ...(dest && state.clip ? [{ label: t('paste'), icon: 'clipboard-paste', shortcut: 'Ctrl V', onSelect: paste }] : []),
