          const item = { name: f.name, size: f.size > 1048576 ? `${(f.size / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(f.size / 1024))} KB`, kind: f.type.startsWith('image/') ? 'image' : f.type === 'application/pdf' ? 'pdf' : 'file' };
